// Comparison spec for the CoCo 3 (GIME). diag.asm (generated by gen-diag.js) is our own 32K firmware,
// installed in place of coco3.rom. MAME stops when the firmware writes phase 10 to $7000.
const path = require('path');
const { loadEmu, assembleFile, romImage, writeRoms, mameConfigArgs, writeCfg } = require('../lib/firmware');
const { REGS } = require('../lib/regs');
const { workDir } = require('../lib/workdir');

// mameCompat reproduces MAME's speed-switch scheduling (off in the product)
function machine(profileId, rom, config = {}) {
  const m = loadEmu().createMachine(profileId, Object.assign({ mameCompat: true }, config));
  m.setRoms({ basic: rom });
  m.reset(true);
  return m;
}

module.exports = {
  family: 'coco3',
  trace(profileId, { regenerate = true, config = {}, work } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    work = work || workDir(`${profileId}-${resolved.ram}`);
    const asm = assembleFile(path.join(__dirname, 'diag.asm'), '6809', regenerate && path.join(__dirname, 'gen-diag.js'));
    const rom = romImage(asm, 0x8000, 0x8000, 0x12);
    return {
      label: `${profileId} ${resolved.ram}K`, system: profile.mame, work, seconds: 10, args: ['-ext', '', ...mameConfigArgs(resolved)],
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      luaPostlude: `local space = manager.machine.devices[":maincpu"].spaces["program"]
local n = 0
emu.register_frame_done(function()
  n = n + 1
  if space:read_u8(0x7000) == 10 or n > 300 then manager.machine:exit() end
end)`,
      install: () => writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }),
      machine: () => machine(profileId, rom, config),
      instructions: 90000,
    };
  },
  // PIA1 port B's input pins (pia1b.asm, the reads in ../sam/pia1b-body.asm)
  pia1b(profileId, { config = {}, work = `/tmp/mame-diff/${profileId}-pia1b` } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const asm = assembleFile(path.join(__dirname, 'pia1b.asm'), '6809');
    const rom = romImage(asm, 0x8000, 0x8000, 0x12);
    return {
      label: `${profileId} ${resolved.ram}K pia1b.asm`, system: profile.mame, work, seconds: 3, args: ['-ext', '', ...mameConfigArgs(resolved)],
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      install: () => writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }),
      machine: () => machine(profileId, rom, config),
      instructions: 400,
    };
  },
  // video register writes swept across the beam (raster.asm, from gen-raster.js; lib/raster.js)
  raster(profileId, { regenerate = true, config = {}, work = workDir(`${profileId}-raster`) } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const gen = require('./gen-raster');
    if (regenerate) gen.write();                   // raster.asm from gen-raster.js
    const asm = assembleFile(path.join(__dirname, 'raster.asm'), '6809');
    const rom = romImage(asm, 0x8000, 0x8000, 0x12);
    return {
      label: `${profileId} ${resolved.ram}K`, system: profile.mame, work, seconds: 6, args: ['-ext', '', ...mameConfigArgs(resolved)],
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      install: () => writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }),
      machine: () => machine(profileId, rom, config),
      phaseAddr: 0x7F00, fieldAddr: 0x7F01, file: 'raster.asm', cases: gen.cases, fields: gen.FIELDS, plain: gen.FIELDS - 2,
      // MAME's bitmap is the 640x240 picture, as ours (scanlines 1-240 of the field); the lead-in fields
      // change the first display byte, at the top left of the active area
      geometry: { offset: () => ({ ox: 0, oy: 0 }), ignore: (x, y) => x < 32 && y >= 16 && y < 48, origin: [0, 0] },
    };
  },
  // printer firmware (lib/printer.js): sam/printer-serial.asm, the bit-banger's serial printer as on the CoCo 1/2,
  // with its vectors at the top of the CoCo 3's 32K ROM
  printer(profileId, { config = {}, work = `/tmp/mame-diff/${profileId}-printer` } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const src = require('fs').readFileSync(path.join(__dirname, '../sam/printer-serial.asm'), 'utf8').replace('ORG     $BFF2', 'ORG     $FFF2');
    const asm = Emu.assemble(src, '6809');
    if (!asm.ok) throw new Error(asm.errors.join('; '));
    const rom = romImage(asm, 0x8000, 0x8000, 0x12);
    return {
      label: `${profileId} ${resolved.ram}K`, system: profile.mame, work, seconds: 12, args: ['-ext', '', ...mameConfigArgs(resolved)],
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      install: () => writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }),
      machine: () => machine(profileId, rom, config),
      instructions: 3000000, doneAddr: 0x7001, text: 'CLOADM PRINTER TEST, COCO SERIAL PORT, 600 BAUD\r\n',
    };
  },
  // the bit-banger in loopback: sam/serial-loopback.asm with its vectors at the top of the 32K ROM (run.js --serial)
  serial(profileId, { config = {}, work = `/tmp/mame-diff/${profileId}-serial` } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const src = require('fs').readFileSync(path.join(__dirname, '../sam/serial-loopback.asm'), 'utf8').replace('ORG     $BFF2', 'ORG     $FFF2');
    const asm = Emu.assemble(src, '6809');
    if (!asm.ok) throw new Error(asm.errors.join('; '));
    const rom = romImage(asm, 0x8000, 0x8000, 0x12);
    const data = asm.symbols.get('DATA'), end = asm.symbols.get('DATAEND');
    return {
      label: `${profileId} ${resolved.ram}K serial loopback`, system: profile.mame, work, seconds: 4,
      args: ['-ext', '', '-rs232', 'loopback', ...mameConfigArgs(resolved)],
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      install: () => writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }),
      // the loopback is plugged in before the machine is reset, as MAME starts with it
      machine: () => {
        const m = loadEmu().createMachine(profileId, Object.assign({ mameCompat: true }, config));
        m.setRoms({ basic: rom }); m.bitBanger.attach('loopback'); m.reset(true);
        return m;
      },
      instructions: 200000,
      result: (m) => {
        const sent = [...rom.slice(data - 0x8000, end - 0x8000)], back = [...m.ram.slice(0x7102, 0x7102 + sent.length)].map((_, i) => m.read(0x7102 + i));
        return { ok: m.read(0x7000) === 0xFF && m.read(0x7001) === 0 && sent.every((v, i) => v === back[i]), sent, back };
      },
    };
  },
  // video firmware (run-vdg.js): every display mode (vdg.asm), or the text attributes (vdg-attr.asm, ATTR=1)
  video(profileId, { file = 'vdg.asm' } = {}) {
    const asm = assembleFile(path.join(__dirname, file), '6809');
    const rom = romImage(asm, 0x8000, 0x8000, 0x12);
    return { machine: () => machine(profileId, rom), frames: 1500 };
  },
  // The Hi-Res joystick interface and "The Rat" mouse on a CoCo 3, in instruction lockstep with MAME. The
  // firmware is the SAM family's (sam/hires.asm, sam/hires-max3.asm): $FF00-$FF23 are the same PIAs, and the
  // CoCo 3 boots it as a 32K internal ROM. The interface comes from MAME's cfg (its Lua API cannot set a port
  // CONFIG field while it runs, lib/firmware.js writeCfg), the stick from Lua (a live input).
  hiresLockstep(profileId, { kind = 'tandy', pos = 682, ram = 128, work = workDir(`${profileId}-hires-lockstep-${kind}`) } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const option = `${kind}-right`;
    const resolved = Emu.resolveConfig(profileId, { mameCompat: true, ram, hires: option });
    const romOf = (file, argv) => {
      require('child_process').execFileSync('node', [path.join(__dirname, '../sam/gen-hires.js'), argv], { stdio: 'ignore' });
      return romImage(assembleFile(path.join(__dirname, '../sam', file), '6809'), 0x8000, 0x8000, 0x12);
    };
    const FILE = kind === 'rat' ? 'hires-rat.asm' : kind === 'max3' ? 'hires-max3.asm' : 'hires.asm';
    const rom = romOf(FILE, kind === 'rat' ? 'rat' : kind === 'max3' ? 'max3' : 'tandy');
    const asm = assembleFile(path.join(__dirname, '../sam', FILE), '6809');
    const axis = Math.round(pos * 63 / 1023);
    // the Rat is a 2-bit quadrature count per axis, so its positions are the four counts MAME's table has
    const ratCount = Math.round((pos / 1023) * 3);
    // MAME's cfg: the right port holds the device (ctrl_sel 2 the Rat, 1 a stick with a Hi-Res interface on it,
    // HIRES_INTF_TAG 1 Tandy / 2 CoCo Max 3 style). The Rat needs no Hi-Res interface.
    const cfgIntf = kind === 'rat' ? 0 : kind === 'max3' ? 2 : 1;
    const cfgRight = kind === 'rat' ? 2 : 1;
    return {
      label: `${profileId} hires ${kind} lockstep, stick ${pos}`, system: profile.mame, work, asm, axis,
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      args: ['-ext', '', ...mameConfigArgs(resolved)],
      // the stick is a live input, set after the trace is running (a port touched before the machine starts
      // raises in the prelude and the trace never begins)
      luaPrelude: '',
      luaPostlude: `local iop = manager.machine.ioport
${kind === 'rat'
  ? `-- the Rat's axes are IPT_MOUSE_X/Y, 2-bit counts in 0..3
iop.ports[":rat_mouse_rx"].fields["Rat Mouse X (Right Port)"]:set_value(${ratCount})
iop.ports[":rat_mouse_ry"].fields["Rat Mouse Y (Right Port)"]:set_value(${ratCount})`
  : `-- the CoCo 3's own input ports name the sticks generically ("AD Stick X"), not "Right Joystick X"
iop.ports[":joystick_rx"].fields["AD Stick X"]:set_value(${pos})
iop.ports[":joystick_ry"].fields["AD Stick Y"]:set_value(${pos})`}
local space = manager.machine.devices[":maincpu"].spaces["program"]
local n = 0
emu.register_frame_done(function()
  n = n + 1
  if space:read_u8(0x100) == 10 or n > 300 then manager.machine:exit() end
end)`,
      install: () => { writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }); writeCfg(work, profile.mame, cfgIntf, cfgRight); },
      machine: () => {
        const m = machine(profileId, rom, { ram, hires: option });
        if (kind === 'rat') m.mouse = { x: ratCount / 3, y: ratCount / 3, left: false, right: false };
        else m.joy[0] = [axis, axis];
        return m;
      },
      instructions: 400000,
    };
  },
};
